CREATE TABLE integration_accounts (id text PRIMARY KEY, org_id text NOT NULL REFERENCES organizations(id), provider text NOT NULL CHECK(provider IN ('meta','razorpay')), model text NOT NULL, account_ref text NOT NULL, template_account_ref text, credential_key text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true, UNIQUE(org_id,id), UNIQUE(provider,account_ref));
CREATE TABLE whatsapp_senders (id text PRIMARY KEY, org_id text NOT NULL, branch_id text NOT NULL, account_id text NOT NULL, phone_id text NOT NULL UNIQUE, display_number text NOT NULL, name text NOT NULL, active boolean NOT NULL DEFAULT true, is_default boolean NOT NULL DEFAULT false, connection_state text NOT NULL DEFAULT 'setup_required', health_checked_at timestamptz, live_verified_at timestamptz, UNIQUE(org_id,id), FOREIGN KEY(org_id,account_id) REFERENCES integration_accounts(org_id,id), FOREIGN KEY(org_id,branch_id) REFERENCES branches(org_id,id));
CREATE UNIQUE INDEX whatsapp_one_default ON whatsapp_senders(org_id,branch_id) WHERE is_default;
CREATE TABLE message_templates (id text PRIMARY KEY, org_id text NOT NULL, account_id text NOT NULL, provider_id text NOT NULL, name text NOT NULL, language text NOT NULL, category text NOT NULL, provider_status text NOT NULL, parameter_count integer NOT NULL CHECK(parameter_count BETWEEN 0 AND 20), supported boolean NOT NULL, body text NOT NULL, version_hash text NOT NULL, synced_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,id), UNIQUE(account_id,provider_id), FOREIGN KEY(org_id,account_id) REFERENCES integration_accounts(org_id,id));
CREATE TABLE recipient_consents (id text PRIMARY KEY, org_id text NOT NULL, branch_id text NOT NULL, user_id text NOT NULL, student_id text, identity text NOT NULL, opted_in boolean NOT NULL, categories jsonb NOT NULL, source text NOT NULL, evidence text NOT NULL, recorded_by text NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now(), opted_out_at timestamptz, UNIQUE(org_id,id), UNIQUE(org_id,user_id,student_id,identity), FOREIGN KEY(org_id,branch_id) REFERENCES branches(org_id,id), FOREIGN KEY(org_id,user_id) REFERENCES users(org_id,id), FOREIGN KEY(org_id,student_id) REFERENCES students(org_id,id), FOREIGN KEY(org_id,recorded_by) REFERENCES users(org_id,id));
CREATE TABLE message_requests (id text PRIMARY KEY, org_id text NOT NULL, branch_id text NOT NULL, actor_id text NOT NULL, sender_id text NOT NULL, template_id text NOT NULL, template_version text NOT NULL, category text NOT NULL, parameters jsonb NOT NULL, purpose text NOT NULL, event_key text NOT NULL, scheduled_at timestamptz NOT NULL, authorized_test boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','queued','processing','completed','cancelled')), confirmed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,id), UNIQUE(org_id,event_key), FOREIGN KEY(org_id,branch_id) REFERENCES branches(org_id,id), FOREIGN KEY(org_id,actor_id) REFERENCES users(org_id,id), FOREIGN KEY(org_id,sender_id) REFERENCES whatsapp_senders(org_id,id), FOREIGN KEY(org_id,template_id) REFERENCES message_templates(org_id,id));
CREATE TABLE message_recipients (id text PRIMARY KEY, org_id text NOT NULL, request_id text NOT NULL, consent_id text NOT NULL, invoice_id text, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','processing','accepted','sent','delivered','read','failed','cancelled','suppressed','uncertain')), provider_message_id text UNIQUE, attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), locked_at timestamptz, error_code text, retryable boolean NOT NULL DEFAULT false, accepted_at timestamptz, sent_at timestamptz, delivered_at timestamptz, read_at timestamptz, UNIQUE(org_id,id), UNIQUE(request_id,consent_id), FOREIGN KEY(org_id,request_id) REFERENCES message_requests(org_id,id), FOREIGN KEY(org_id,consent_id) REFERENCES recipient_consents(org_id,id));
CREATE INDEX message_dispatch ON message_recipients(status,next_attempt_at);
CREATE TABLE message_attempts (id text PRIMARY KEY, org_id text NOT NULL, recipient_id text NOT NULL, number integer NOT NULL, outcome text NOT NULL, provider_message_id text, error_code text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(recipient_id,number), FOREIGN KEY(org_id,recipient_id) REFERENCES message_recipients(org_id,id));
CREATE TABLE webhook_events (id text PRIMARY KEY, org_id text NOT NULL, account_id text NOT NULL, provider text NOT NULL, event_hash text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'queued', error_code text, created_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, UNIQUE(account_id,event_hash), FOREIGN KEY(org_id,account_id) REFERENCES integration_accounts(org_id,id));
CREATE TABLE delivery_events (id text PRIMARY KEY, org_id text NOT NULL, recipient_id text NOT NULL, event_key text NOT NULL UNIQUE, status text NOT NULL, provider_time timestamptz NOT NULL, error_code text, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(org_id,recipient_id) REFERENCES message_recipients(org_id,id));
CREATE TABLE inbound_messages (id text PRIMARY KEY, org_id text NOT NULL, sender_id text NOT NULL, provider_message_id text NOT NULL UNIQUE, provider_identity text NOT NULL, consent_id text, text text NOT NULL, received_at timestamptz NOT NULL, context_message_id text, UNIQUE(org_id,id), FOREIGN KEY(org_id,sender_id) REFERENCES whatsapp_senders(org_id,id), FOREIGN KEY(org_id,consent_id) REFERENCES recipient_consents(org_id,id));
CREATE TABLE sender_routes (org_id text NOT NULL, branch_id text NOT NULL, category text NOT NULL, sender_id text NOT NULL, template_id text NOT NULL, PRIMARY KEY(org_id,branch_id,category), FOREIGN KEY(org_id,branch_id) REFERENCES branches(org_id,id), FOREIGN KEY(org_id,sender_id) REFERENCES whatsapp_senders(org_id,id), FOREIGN KEY(org_id,template_id) REFERENCES message_templates(org_id,id));
